[CmdletBinding()]param([string]$CommandName='help',[string]$Target='')
. (Join-Path $PSScriptRoot 'lib\runtime.ps1');Initialize-Module $PSScriptRoot
$Port=9000;$Console=9001;$Exe=Join-Path $PSScriptRoot 'runtime\silo.exe';$Secrets=Join-Path $StateRoot 'secrets.json'
function Verify-Payload{Test-Payload;& $Exe --version;if($LASTEXITCODE -ne 0){throw 'Silo version probe failed'}}
function Install-Silo{Begin-Install;Test-Payload;& $Exe --version;if($LASTEXITCODE -ne 0){throw 'Silo version probe failed'};if(Test-Path $Secrets){$s=Read-Json $Secrets}else{$s=[ordered]@{username='localadmin';password=New-HexSecret 24};Write-JsonAtomic $Secrets $s};Write-Connection ([ordered]@{schema=1;module='silo';endpoint="127.0.0.1:$Port";console="127.0.0.1:$Console";username=$s.username;password=$s.password});Set-Installed;Write-Host '[OK] silo installed'}
function Start-Silo{$s=Read-Json $Secrets;$env:MINIO_ROOT_USER=$s.username;$env:MINIO_ROOT_PASSWORD=$s.password;$env:MINIO_BROWSER='off';$env:MINIO_UPDATE='off';Start-OwnedProcess 'silo' $Exe @('server',(Join-Path $DataRoot 'objects'),'--address',"127.0.0.1:$Port",'--console-address',"127.0.0.1:$Console") (Split-Path $Exe);Wait-Healthy 'silo' {Test-Http "http://127.0.0.1:$Port/minio/health/ready"}}
switch($CommandName.ToLowerInvariant()){'install'{Install-Silo}'start'{Assert-Installed;Start-Silo}'stop'{Stop-OwnedProcess 'silo'}'status'{Show-ModuleStatus @('silo')}'verify'{Test-Payload;if((Get-OwnedProcess 'silo')-and -not(Test-Http "http://127.0.0.1:$Port/minio/health/ready")){throw 'Silo health failed'};Write-Host '[OK] silo verified'}'verify-payload'{Verify-Payload}default{Write-Host 'Usage: MODULE.bat install|start|stop|status|verify';if($CommandName -ne 'help' -and $CommandName){exit 2}}}
